"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useMemo } from "react";

import { cn } from "@/lib/utils";

/** Props for a read-only number whose digits roll when it changes. */
export type NumberTickerProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  value: number;
  /** A BCP 47 locale such as "en-GB". It defaults to "en-US", so the server and the browser render the same text. */
  locale?: string;
  /** Formats the number, for example `{ style: "currency", currency: "EUR" }`. */
  format?: Intl.NumberFormatOptions;
};

// The system announces a new figure, so the roll is an ease-out that lands
// once. A spring would keep the digits restless after the value settled.
const ROLL: Transition = { duration: 0.6, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

function DigitColumn({ digit, digits, transition }: { digit: number; digits: string[]; transition: Transition }) {
  return (
    <span className="relative inline-block overflow-hidden">
      {/* The invisible zero sizes the window, so the column needs no measured height. */}
      <span className="invisible">{digits[0]}</span>
      <motion.span
        initial={false}
        animate={{ y: `${-digit * 10}%` }}
        transition={transition}
        className="absolute inset-x-0 top-0 flex flex-col items-center"
      >
        {digits.map((glyph) => (
          <span key={glyph}>{glyph}</span>
        ))}
      </motion.span>
    </span>
  );
}

/**
 * Shows a figure, such as revenue or a visitor count, whose digits roll to the
 * new value when it changes. It shows the first value at once: there is no
 * entrance count-up, because the number is already known.
 */
export function NumberTicker({ value, locale = "en-US", format, className, ...spanProps }: NumberTickerProps) {
  const reduceMotion = useReducedMotion();
  const formatter = useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);
  const text = formatter.format(value);
  // A locale may write digits in another script, such as Arabic-Indic. The
  // columns roll through that script's ten digits, read from the formatter.
  const digits = useMemo(() => {
    const plain = new Intl.NumberFormat(locale, { numberingSystem: formatter.resolvedOptions().numberingSystem, useGrouping: false });
    return Array.from({ length: 10 }, (_, digit) => plain.format(digit));
  }, [formatter, locale]);
  // Each glyph is keyed by its place from the right. A digit that changes keeps
  // its column and rolls; a number that grows adds columns on the left only.
  const glyphs = [...text].map((char, index, all) => ({ char, place: all.length - 1 - index }));
  const transition = reduceMotion ? INSTANT : ROLL;

  return (
    <span {...spanProps} className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map(({ char, place }) =>
          digits.includes(char) ? (
            <DigitColumn key={place} digit={digits.indexOf(char)} digits={digits} transition={transition} />
          ) : (
            // A space must keep its width, or "48 km" would render as "48km".
            <span key={place} className="whitespace-pre">
              {char}
            </span>
          ),
        )}
      </span>
    </span>
  );
}
